def weakCauchyValue (u : ℕ → E)
    (hconv : ∀ φ : E →L[𝕜] 𝕜, ∃ a : 𝕜, Tendsto (fun n => φ (u n)) atTop (𝓝 a))
    (φ : E →L[𝕜] 𝕜) : 𝕜 := (hconv φ).choose

